fn get_beacon_color(state: i32) -> color {
    let idle_color = #3a3a3a;
    let running_color = #ffb000;
    let done_color = #22c55e;
    let is_running = step(0.5, f32(state - 0));
    let is_done = step(0.5, f32(state - 1));
    let color_a = mix(idle_color, running_color, is_running);
    let color_b = mix(color_a, done_color, is_done);
    return color_b;
}
