1. Track which Pips currently exist (as a list of their x positions)
2. Handle Space key to add a Pip at the next free position (-4, -2, 0, 2, 4)
3. Handle Backspace key to remove the most recently added Pip
4. Handle Enter key to remove all Pips
5. Use scene state to track the Pips and spawn/destroy them dynamically

The key positions follow the pattern: x = -6 + 2n, so for n=0,1,2,3,4 we get x = -4, -2, 0, 2, 4.

I'll need to:
- Store entity references to the spawned Pips in an array
- Track how many Pips exist
- Handle key events to add/remove Pips dynamically

<<<FILE src/main.mtek
<<<WHOLE
prefab Pip {
    param x: f32;
    position: vec3(x, 0.0, 0.0);
    mesh: Box { size: vec3(0.8, 0.8, 0.5) };
    material: Unlit { color: #38bdf8 };
}

scene Demo {
    clear_color: #202020;
    state pip_count: i32 = 0;
    state pips: array<entity_ref, 5>;

    camera Main {
        position: vec3(0.0, 0.0, 10.0);
        target: vec3(0.0, 0.0, 0.0);
        projection: Orthographic { height: 12.8 };
    }

    entity Rail {
        position: vec3(0.0, -1.5, 0.0);
        mesh: Box { size: vec3(12.0, 0.2, 0.2) };
        material: Unlit { color: #404040 };
    }

    on key_down(key: Key) {
        if key == Key.Space {
            if pip_count < 5 {
                let x: f32 = -4.0 + 2.0 * (pip_count as f32);
                pips[pip_count] = spawn(Pip { x: x; });
                pip_count = pip_count + 1;
            }
        } else if key == Key.BackSpace {
            if pip_count > 0 {
                pip_count = pip_count - 1;
                destroy(pips[pip_count]);
            }
        } else if key == Key.Return {
            let i: i32 = 0;
            for i in 0 .. pip_count {
                destroy(pips[i]);
            }
            pip_count = 0;
        }
    }
}
>>>END
```

