1. Can't use ternary operator - need to use `if` statements instead
2. Can't declare functions inside a scene - need to use `const` with material definitions or handle colors differently
3. The `key_down` event doesn't take a parameter - I need to use `is_key_down()` function
4. Key.Return should be Key.Enter

The best approach is to use `const` materials with their colors set based on scene state, or directly update material colors. Let me use state variables to track colors and update them with the keyboard handler.

<<<FILE src/main.mtek
<<<SEARCH
scene Demo {
    clear_color: #202020;

    state lampA_on: bool = false;
    state lampB_on: bool = false;

    camera Main {
        position: vec3(0.0, 0.0, 10.0);
        target: vec3(0.0, 0.0, 0.0);
        projection: Orthographic { height: 12.8 };
    }

    entity LampA {
        position: vec3(-3.0, 0.0, 0.0);
        mesh: Box { size: vec3(2.0, 2.0, 0.5) };
        material: Unlit { color: bind(lampA_color); };
    }

    entity LampB {
        position: vec3(3.0, 0.0, 0.0);
        mesh: Box { size: vec3(2.0, 2.0, 0.5) };
        material: Unlit { color: bind(lampB_color); };
    }

    fn lampA_color() -> color {
        return lampA_on ? #ffd24a : #3a3a3a;
    }

    fn lampB_color() -> color {
        return lampB_on ? #ffd24a : #3a3a3a;
    }

    on key_down(key: Key) {
        if (key == Key.A) {
            lampA_on = !lampA_on;
        }
        if (key == Key.B) {
            lampB_on = !lampB_on;
        }
        if (key == Key.Space) {
            lampA_on = !lampA_on;
            lampB_on = !lampB_on;
        }
        if (key == Key.Return) {
            lampA_on = false;
            lampB_on = false;
        }
    }
}
