const picture: texture = asset.texture("assets/swatch.png");

const plain_sampler: sampler = sampler.nearest_clamp();
const tiled_sampler: sampler = sampler.nearest_repeat();
const smooth_sampler: sampler = sampler.linear_clamp();

material PlainMaterial {
  fn fragment(input: SurfaceInput) -> color {
    let uv: vec2 = vec2(input.uv.x, 1.0 - input.uv.y);
    let tex: vec4 = sample(picture, plain_sampler, uv);
    return color.linear(tex.rgb, tex.a);
  }
}

material TiledMaterial {
  fn fragment(input: SurfaceInput) -> color {
    let uv: vec2 = vec2(input.uv.x, 1.0 - input.uv.y);
    let tex: vec4 = sample(picture, tiled_sampler, uv);
    return color.linear(tex.rgb, tex.a);
  }
}

material SmoothMaterial {
  fn fragment(input: SurfaceInput) -> color {
    let uv: vec2 = vec2(input.uv.x, 1.0 - input.uv.y);
    let tex: vec4 = sample(picture, smooth_sampler, uv);
    return color.linear(tex.rgb, tex.a);
  }
}

