// Custom material for color sweep effect
material Sweep {
    param time: f32 = 0.0;

    fragment(input: SurfaceInput) -> color {
        // Get object-space X coordinate (converted from world space)
        let x = input.local_position.x;

        // Compute the blend factor w = 0.5 + 0.5 * sin(0.8 * x + t)
        let w = 0.5 + 0.5 * sin(0.8 * x + time);

        // Color A: #1a237e (sRGB) converted to linear
        let A = color.srgb(vec3(26.0 / 255.0, 35.0 / 255.0, 126.0 / 255.0), 1.0);

        // Color B: #ffb300 (sRGB) converted to linear
        let B = color.srgb(vec3(255.0 / 255.0, 179.0 / 255.0, 0.0 / 255.0), 1.0);

        // Blend in linear light: (1-w)*A + w*B
        // Extract linear RGB components
        let A_rgb = A.rgb;
        let B_rgb = B.rgb;
        let blended_rgb = (1.0 - w) * A_rgb + w * B_rgb;

        // Return the blended color
        return color.linear(blended_rgb, 1.0);
    }
}

