I'll build a scene that renders a panel with a color that sweeps over time based on the x-coordinate and elapsed time.

Let me analyze the requirements:
1. Scene named "Demo" with clear color #202020
2. Camera at (0, 0, 6) looking at origin with perspective projection (fov 0.9, near 0.1, far 1000)
3. A box named "Panel" at (0.4, 0, 0), size 4×2×0.2
4. Custom material "Sweep" that computes color based on x coordinate and time
5. The color formula: `w = 0.5 + 0.5 * sin(0.8 * x + t)`, then `(1-w)*A + w*B` where A=#1a237e, B=#ffb300
6. Blend in linear light (sRGB colors converted to linear, result displayed as-is)
7. Material parameter `t` that updates every frame

<<<FILE src/main.mtek
<<<WHOLE
material Sweep {
    param time: f32 = 0.0;

    fragment(input: SurfaceInput) -> color {
        let x = input.local_position.x;
        let t = time;

        // Compute the blend factor
        let w = 0.5 + 0.5 * sin(0.8 * x + t);

        // Color A: #1a237e in sRGB, convert to linear
        let A = color.srgb(vec3(26.0 / 255.0, 35.0 / 255.0, 126.0 / 255.0), 1.0);

        // Color B: #ffb300 in sRGB, convert to linear
        let B = color.srgb(vec3(1.0, 179.0 / 255.0, 0.0), 1.0);

        // Linear blend: (1-w)*A + w*B
        // Both A and B are already in linear light from color.srgb
        let result_rgb = (1.0 - w) * A.rgb + w * B.rgb;

        // Return as linear color
        return color.linear(result_rgb, 1.0);
    }
}

scene Demo {
    clear_color: #202020;

    camera Main {
        position: vec3(0.0, 0.0, 6.0);
        target: vec3(0.0, 0.0, 0.0);
        projection: Perspective {
            fov_y: 0.9;
            near: 0.1;
            far: 1000.0;
        };
    }

    entity Panel {
        position: vec3(0.4, 0.0, 0.0);
        mesh: Box { size: vec3(4.0, 2.0, 0.2) };
        material: Sweep { time: bind(frame.time) };
    }
}
